<script>
 import {onMount} from "svelte";
 let report=null,verification=null,loading=true;
 onMount(()=>{Promise.all([fetch("/data/official-source-monitor.json",{cache:"no-store"}).then(r=>r.ok?r.json():null),fetch("/data/official-policy-automation.json",{cache:"no-store"}).then(r=>r.ok?r.json():null)]).then(([links,rates])=>{report=links;verification=rates;}).catch(()=>{}).finally(()=>loading=false)});
</script>
<section class="monitor"><h2>Automated official-source checks</h2><p>Official links are checked automatically. Supported rate-decision documents undergo additional bank-specific verification before any policy rate can change.</p>{#if loading}<p>Loading monitor status…</p>{:else if !report?.sources?.length}<p>First monitoring run not yet published.</p>{:else}<p>Last scan: {report.lastScanAt || "Not yet"} · {report.sources.filter(s=>s.status==="available").length}/8 channels accessible.</p><p class="autoverify"><strong>Automatic rate verification:</strong> {verification?.lastCheckedAt ? "Last verified-source check "+verification.lastCheckedAt+" · "+verification.coverage.filter(x=>/matches|Verified new decision/i.test(x.state)).length+"/8 bank decisions directly validated in latest run" : "Awaiting first published verification run"} · No inferred or invented policy rates.</p><div class="sources">{#each report.sources as s}<article><strong>{s.code} · {s.bank}</strong><p>{s.status==="available"?"Official source reached":"Requires attention"}</p><a href={s.url} target="_blank" rel="noopener noreferrer">View bank source ↗</a></article>{/each}</div>{/if}<p class="caveat">Automatic rate updates publish only when both the official benchmark and effective date pass source-specific validation. Unknown formats, PDF-only decisions and ambiguous cases retain the last verified figure; check the separate snapshot date.</p></section>
<style>.monitor{border:1px solid #334155;border-radius:12px;padding:18px;margin:20px 0;background:#111c30;color:#f8fafc}.monitor h2{font-size:1.3rem;margin:0}.monitor>p{font-size:.91rem;line-height:1.6;color:#cbd5e1}.sources{display:grid;grid-template-columns:repeat(4,1fr);gap:9px}.sources article{padding:12px;background:#18263a;border:1px solid #334155;border-radius:10px}.sources article strong{font-size:.88rem;color:#f8fafc}.sources article p{font-size:.82rem;color:#cbd5e1}.sources article a{color:#6ee7b7;font-size:.85rem}.monitor .caveat,.monitor .autoverify{font-size:.85rem}@media(max-width:800px){.sources{grid-template-columns:repeat(2,1fr)}}@media(max-width:480px){.sources{grid-template-columns:1fr}}:global(html[data-theme="light"]) .monitor{background:#fff;color:#102033;border-color:#cbd5e1}:global(html[data-theme="light"]) .monitor h2{color:#102033}:global(html[data-theme="light"]) .monitor>p{color:#334155}:global(html[data-theme="light"]) .sources article{background:#f8fafc;border-color:#cbd5e1}:global(html[data-theme="light"]) .sources article strong{color:#102033}:global(html[data-theme="light"]) .sources article p{color:#334155}:global(html[data-theme="light"]) .sources article a{color:#065f46}</style>